import { RouteTable } from "../domain/route-table.js";
import type { HttpMethod, RateLimitPolicy, RouteAuth, RouteDefinition } from "../domain/route.js";
import type { ServiceCatalog } from "../domain/service-catalog.js";

/**
 * The reference route table.
 *
 * Rather than hand-writing five near-identical entries per resource, the
 * standard read/write surface is generated by {@link resourceRoutes} and the
 * genuinely interesting operations (state transitions, reports, bulk jobs) are
 * declared explicitly. Every entry still carries its own auth mode, rate
 * limit and tags, so nothing is lost to the shorthand.
 */

const READ_LIMIT: RateLimitPolicy = { limit: 600, windowMs: 60_000, key: "tenant" };
const WRITE_LIMIT: RateLimitPolicy = { limit: 120, windowMs: 60_000, key: "tenant-user" };
const HEAVY_LIMIT: RateLimitPolicy = { limit: 20, windowMs: 60_000, key: "tenant" };

export interface ResourceRoutesInput {
  readonly service: string;
  readonly prefix: string;
  /** Collection path relative to the prefix, e.g. `products`. */
  readonly resource: string;
  readonly idParam?: string;
  readonly readRoles?: readonly string[];
  readonly writeRoles?: readonly string[];
  readonly readPermission?: string;
  readonly writePermission?: string;
  readonly operations?: readonly ("list" | "get" | "create" | "update" | "delete")[];
  readonly tags?: readonly string[];
}

function auth(roles: readonly string[] | undefined, permission?: string): RouteAuth {
  if (!roles || roles.length === 0) {
    return permission ? { mode: "tenant", allOfPermissions: [permission] } : { mode: "tenant" };
  }
  return {
    mode: "roles",
    anyOfRoles: roles,
    allOfPermissions: permission ? [permission] : undefined,
  };
}

export function resourceRoutes(input: ResourceRoutesInput): RouteDefinition[] {
  const idParam = input.idParam ?? "id";
  const base = `${input.prefix}/${input.resource}`;
  const item = `${base}/:${idParam}`;
  const tags = input.tags ?? [input.resource];
  const operations = input.operations ?? ["list", "get", "create", "update", "delete"];
  const readAuth = auth(input.readRoles, input.readPermission);
  const writeAuth = auth(input.writeRoles, input.writePermission);

  const all: Record<string, RouteDefinition> = {
    list: {
      id: `${input.service}.${input.resource}.list`,
      method: "GET",
      pattern: base,
      upstream: input.service,
      auth: readAuth,
      rateLimit: READ_LIMIT,
      summary: `List ${input.resource}`,
      tags,
      idempotent: true,
    },
    get: {
      id: `${input.service}.${input.resource}.get`,
      method: "GET",
      pattern: item,
      upstream: input.service,
      auth: readAuth,
      rateLimit: READ_LIMIT,
      summary: `Fetch one ${singular(input.resource)}`,
      tags,
      idempotent: true,
    },
    create: {
      id: `${input.service}.${input.resource}.create`,
      method: "POST",
      pattern: base,
      upstream: input.service,
      auth: writeAuth,
      rateLimit: WRITE_LIMIT,
      summary: `Create a ${singular(input.resource)}`,
      tags,
    },
    update: {
      id: `${input.service}.${input.resource}.update`,
      method: "PATCH",
      pattern: item,
      upstream: input.service,
      auth: writeAuth,
      rateLimit: WRITE_LIMIT,
      summary: `Update a ${singular(input.resource)}`,
      tags,
    },
    delete: {
      id: `${input.service}.${input.resource}.delete`,
      method: "DELETE",
      pattern: item,
      upstream: input.service,
      auth: writeAuth,
      rateLimit: WRITE_LIMIT,
      summary: `Delete a ${singular(input.resource)}`,
      tags,
    },
  };

  return operations.map((operation) => all[operation]!);
}

export interface ActionRouteInput {
  readonly service: string;
  readonly method: HttpMethod;
  readonly pattern: string;
  readonly id: string;
  readonly summary: string;
  readonly auth?: RouteAuth;
  readonly roles?: readonly string[];
  readonly permission?: string;
  readonly rateLimit?: RateLimitPolicy;
  readonly tags?: readonly string[];
  readonly rewrite?: string;
  readonly timeoutMs?: number;
}

export function actionRoute(input: ActionRouteInput): RouteDefinition {
  return {
    id: input.id,
    method: input.method,
    pattern: input.pattern,
    upstream: input.service,
    auth: input.auth ?? auth(input.roles, input.permission),
    rateLimit: input.rateLimit ?? WRITE_LIMIT,
    summary: input.summary,
    tags: input.tags,
    rewrite: input.rewrite,
    timeoutMs: input.timeoutMs,
  };
}

