export function buildRouteTable(catalog?: ServiceCatalog): RouteTable {
  const table = new RouteTable(buildRouteDefinitions());
  if (catalog) {
    const findings = table.audit(catalog.ids());
    const unknown = findings.filter((f) => f.includes("unknown upstream"));
    if (unknown.length > 0) {
      throw new Error(`Route table references unknown services:\n  ${unknown.join("\n  ")}`);
    }
  }
  return table;
}

function singular(resource: string): string {
  if (resource.endsWith("ies")) return `${resource.slice(0, -3)}y`;
  if (resource.endsWith("s")) return resource.slice(0, -1);
  return resource;
}
